-- ============================================================================
-- Migration: 000026_restructure_n5_30_interleaved_micro_units.up.sql
-- Description:
--   Restructure JLPT N5 curriculum into 30 sequential, Spiral-Interleaved
--   Micro-Units with 4 structured nodes per unit (120 lessons total):
--     Node 1: Review Unit Sebelumnya + Teori & Praktik Huruf/Konsep Baru
--     Node 2: Kosakata Gabungan (menggunakan huruf dari unit sebelumnya & baru)
--     Node 3: Teori Pola & Bikin Kalimat Sehari-hari
--     Node 4: Praktik Ngomong (Speaking), Menulis (Writing), Membaca & Mendengar
-- ============================================================================

BEGIN;

-- ----------------------------------------------------------------------------
-- 1. UPDATE EXISTING 8 UNITS IN-PLACE (KEEPING HISTORICAL UUIDS INTACT)
-- ----------------------------------------------------------------------------
UPDATE units SET order_index = 1,
    title = 'Hiragana 1: Vokal (あ–お) & Deret K (か–こ)',
    description = 'Mulai dari nol: teori 10 huruf pertama, kosakata pendek, kalimat sapaan awal, serta praktik ngomong, tulis & baca.'
WHERE id = 'a0000002-0000-0000-0000-000000000002'::uuid;

UPDATE units SET order_index = 6,
    title = 'Kepemilikan (の), Kata Tunjuk (この・その) & Benda Sekitar',
    description = 'Review Tahap 1, Kanji awal, kosakata benda kelas, kalimat kepemilikan の, serta praktik ngomong, tulis & baca.'
WHERE id = 'a0000001-0000-0000-0000-000000000001'::uuid;

UPDATE units SET order_index = 11,
    title = 'Katakana Batch 2 (ナ–ホ), Menu Kafe & Partikel Objek を',
    description = 'Review waktu & Katakana 1, kuasai menu kafe, kalimat pesan dengan を, serta praktik ngomong, tulis & baca.'
WHERE id = 'a0000001-0000-0000-0000-000000000003'::uuid;

UPDATE units SET order_index = 15,
    title = 'Transportasi (で), Arah (へ), Rentang (から～まで) & Ujian Tahap 3',
    description = 'Review ajakan, verba gerak & kendaraan, kalimat rute harian, serta praktik 4 pilar & Ujian Tahap 3.'
WHERE id = 'a0000001-0000-0000-0000-000000000004'::uuid;

UPDATE units SET order_index = 16,
    title = 'Katakana Batch 3 (マ–ロ): Fasilitas Kota & Keberadaan (あります・います)',
    description = 'Review Tahap 3, kuasai Katakana fasilitas kota, kalimat keberadaan statis, serta praktik ngomong, tulis & baca.'
WHERE id = 'a0000001-0000-0000-0000-000000000005'::uuid;

UPDATE units SET order_index = 18,
    title = 'Katakana Batch 4 (ワ–ン): Tuntas 46 Huruf & Kata Sifat-I (い)',
    description = 'Review posisi, tuntaskan Katakana (シ/ツ vs ソ/ン), negasi Sifat-I, serta praktik ngomong, tulis & baca.'
WHERE id = 'a0000001-0000-0000-0000-000000000006'::uuid;

UPDATE units SET order_index = 21,
    title = 'Konjugasi Bentuk-TE (て-Form), Permintaan (～てください) & Arah Jalan',
    description = 'Review Tahap 4, kuasai konjugasi Bentuk-TE Grup 1-3, kalimat arah jalan, serta praktik ngomong, tulis & baca.'
WHERE id = 'a0000001-0000-0000-0000-000000000007'::uuid;

UPDATE units SET order_index = 26,
    title = 'Masa Lampau (～ました), Pengalaman (～たことがある) & Akhir Pekan',
    description = 'Review Tahap 5, kuasai Bentuk-TA, kalimat cerita kemarin & pengalaman, serta praktik ngomong, tulis & baca.'
WHERE id = 'a0000001-0000-0000-0000-000000000008'::uuid;

