-- 2. INSERT 22 NEW MICRO-UNITS FOR JLPT N5 (TOTAL 30 MICRO-UNITS)
-- ----------------------------------------------------------------------------
INSERT INTO units (id, level_id, title, description, unit_type, order_index)
SELECT v.id, pl.id, v.title, v.description, 'curriculum', v.order_index
