JOIN languages l ON pl.language_id = l.id
CROSS JOIN (
    VALUES
        ('a0000026-0000-0000-0000-000000000002'::uuid, 'Hiragana 2 (さ–の), Review あ–こ, Salam & Kata Tunjuk (これ・それ)', 'Review あ–こ lalu kuasai deret S-T-N, kosakata gabungan, kalimat salam, serta praktik ngomong, tulis & baca.', 2),
        ('a0000026-0000-0000-0000-000000000003'::uuid, 'Hiragana 3 (は–よ), Review あ–の & Kalimat Nominal (は・です)', 'Review あ–の lalu kuasai deret H-M-Y, kosakata gabungan, kalimat perkenalan は/です, & praktik 4 keterampilan.', 3),
        ('a0000026-0000-0000-0000-000000000004'::uuid, 'Hiragana 4 (ら–ん: Tuntas 46!), Review あ–よ, Kewarganegaraan & あれ', 'Review あ–よ lalu tuntaskan 46 Hiragana, kata kewarganegaraan, kalimat あれ, serta praktik ngomong, tulis & baca.', 4),
