        ('a0000026-0000-0000-0000-000000000014'::uuid, 'Ajakan Sopan (～ませんか/～ましょう) & Kata Sambung Kalimat', 'Review partikel で, kuasai kosakata ajakan & konjungsi, kalimat mengajak teman, serta praktik 4 keterampilan.', 14),
        ('a0000026-0000-0000-0000-000000000017'::uuid, 'Posisi Spasial (うえ・した・となり), Daftar と vs や & Kanji Arah', 'Review keberadaan, kuasai 8 Kanji arah, kosakata posisi, kalimat と vs や, serta praktik ngomong, tulis & baca.', 17),
        ('a0000026-0000-0000-0000-000000000019'::uuid, 'Warna, Belanja & Verba Pakaian (着ます・履きます・かぶります)', 'Review Sifat-I, kuasai Kanji warna & harga, 4 verba pakaian, kalimat belanja どんな, & praktik 4 keterampilan.', 19),
        ('a0000026-0000-0000-0000-000000000020'::uuid, 'Kata Sifat-Na, Cuaca, Lampau Sifat, Perbandingan & Ujian Tahap 4', 'Review pakaian & Sifat-I, kuasai Sifat-Na, kosakata cuaca/kesukaan, kalimat perbandingan, & Ujian Tahap 4.', 20),
        ('a0000026-0000-0000-0000-000000000022'::uuid, 'Urutan Aksi (～てから) & Sedang Berlangsung / Status (～ています)', 'Review Bentuk-TE, kuasai urutan ～てから, kosakata status harian, kalimat ～ています, & praktik 4 keterampilan.', 22),
