        ('a0000026-0000-0000-0000-000000000025'::uuid, 'Sambungan Sifat (～くて/～で), Perubahan Keadaan & Ujian Tahap 5', 'Review klinik, kuasai sambung sifat ～くて/で, kosakata deskriptif, perubahan ～くなる/になる, & Ujian Tahap 5.', 25),
        ('a0000026-0000-0000-0000-000000000027'::uuid, 'Bentuk Kamus (辞書形), Hobi, Sebelum (～まえに) & Ketika (～とき)', 'Review Bentuk-TA, kuasai Bentuk Kamus, kosakata hobi & kemampuan, kalimat まえに/とき, & praktik 4 keterampilan.', 27),
        ('a0000026-0000-0000-0000-000000000028'::uuid, 'Kalimat Kasual (普通形), Opini, Anak Kalimat Nomina & Ujian Tahap 6', 'Review Bentuk Kamus, kuasai gaya kasual 普通形, kosakata opini, anak kalimat nomina, & Ujian Tahap 6.', 28),
