        ('a0000026-0000-0000-0000-000000000030'::uuid, 'Konsolidasi Total JLPT N5 & Simulasi Ujian Kesiapan N5', 'Review seluruh 46 Hiragana, 46 Katakana, 50+ Kanji, kosakata jebakan, grammar kontras, & simulasi 4 pilar N5.', 30)
) AS v(id, title, description, order_index)
WHERE l.code = 'ja' AND pl.code = 'N5'
ON CONFLICT (id) DO UPDATE SET
    title       = EXCLUDED.title,
    description = EXCLUDED.description,
    order_index = EXCLUDED.order_index;

