        ('c0000026-0000-0000-0000-000000010201'::uuid, 'b0000026-0000-0000-0000-000000000102'::uuid, NULL, 'reading', 'fill_blank', 'Dari huruf あ–こ, pilih vokal yang tepat untuk menyusun kata "rumah" (ie):', '{"sentence_template":"い [blank] (rumah = ie)","translation":"Rumah (ie)","options":["え","あ","お","う"]}'::jsonb, '{"selected":"え"}'::jsonb, 'い (i) + え (e) = いえ (rumah).', 1),
        ('c0000026-0000-0000-0000-000000010202'::uuid, 'b0000026-0000-0000-0000-000000000102'::uuid, NULL, 'listening', 'listening_choice', 'Dengarkan kata yang tersusun dari huruf あ–こ ini:', '{"audio_text":"かお","options":[{"id":"opt_1","text":"Wajah (kao)"},{"id":"opt_2","text":"Biru (aoi)"},{"id":"opt_3","text":"Musim gugur (aki)"},{"id":"opt_4","text":"Atas (ue)"}]}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, 'か (ka) + お (o) = かお (wajah).', 2),
