INSERT INTO exercises (
    id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt,
    content, correct_answer, explanation, order_index
)
SELECT
    s.ex_id,
    s.lesson_id,
    gp.id,
    s.skill_pillar,
    s.exercise_type,
    s.prompt,
    s.content,
    s.correct_answer,
    s.explanation,
    s.order_index
FROM ex_seed s
LEFT JOIN grammar_points gp
    ON gp.code = s.gp_code
    AND gp.level_id = (
        SELECT pl.id
        FROM proficiency_levels pl
        JOIN languages lg ON pl.language_id = lg.id
        WHERE lg.code = 'ja' AND pl.code = 'N5'
        LIMIT 1
    )
ON CONFLICT (id) DO UPDATE SET
    lesson_id        = EXCLUDED.lesson_id,
    grammar_point_id = EXCLUDED.grammar_point_id,
    skill_pillar     = EXCLUDED.skill_pillar,
    exercise_type    = EXCLUDED.exercise_type,
    prompt           = EXCLUDED.prompt,
    content          = EXCLUDED.content,
    correct_answer   = EXCLUDED.correct_answer,
    explanation      = EXCLUDED.explanation,
    order_index      = EXCLUDED.order_index;

COMMIT;